import {ArmoryCatalog,ARMORY_CATEGORIES,ARMORY_TRAITS,ARMORY_STATUSES,ARMORY_SORTS,armoryCardState} from './armory-catalog-model.mjs';
import {ARMORY_DEPARTMENTS} from './armory-catalog-data.mjs';
import {getCardInsights,getRankPreview} from './armory-insights.mjs';
const escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const number=value=>Number(value).toLocaleString(undefined,{maximumFractionDigits:2});
const options=items=>items.map(([id,label])=>`<option value="${escape(id)}">${escape(label)}</option>`).join('');
const categoryLabel=category=>ARMORY_CATEGORIES.find(([id])=>id===category)?.[1]??category;
const traitLabel=trait=>ARMORY_TRAITS.find(([id])=>id===trait)?.[1]??trait;
const roles=[['all','All army roles'],['frontline','Frontline'],['ranged','Ranged'],['support','Support'],['siege','Siege']];
const statusLabel=(item,state)=>state.owned?(item.kind==='companion'?(state.equipped?'Companion equipped':'Companion in reserve'):`Rank ${state.skill?.rank??0} · ${state.equipped?'Equipped':'In reserve'}`):state.purchaseBlockedReason??(state.eligible?'Available to acquire':`Need ${number(state.shortfall)} more gold`);
const actionLabel=(item,state)=>state.owned?(item.kind==='companion'?'Manage companion slot':'Arrange in loadout'):state.purchaseBlockedReason??`${item.kind==='companion'?'Hire':'Unlock'} · ${number(item.price)} gold`;
const stateKey=state=>[state.owned,state.eligible,state.purchaseBlockedReason,state.equipped,state.shortfall,state.skill?.rank,state.skill?.binding,state.skill?.xp,state.skill?.threshold,state.skill?.autocast].join(':');
const metricValue=metric=>metric?`${number(metric.value)}${metric.unit?' '+metric.unit:''}`:'—';

/** A bounded storefront journey: Discover → typed catalog / collection →
 * detail / compare → acquire → slot preview → equip. Catalog controls stay
 * mounted, and the last browse state survives every drill-in and reopen.
 */
export function createArmoryCatalogUI({root,records,getSnapshot,onPurchase,onArrange,onEquip=()=>false,onAutocast=()=>false,onCompanionEquip=()=>false,icon=()=>'',nameForId=id=>id,bindingLabel=binding=>binding<0?'Reserve':`Slot ${binding+1}`,keyLabel=slot=>String((slot+1)%10),announce=()=>{},isPortrait=()=>false,pageSize,selectedId,startRefined=false,departments=ARMORY_DEPARTMENTS}){
 const document=root.ownerDocument,model=new ArmoryCatalog(records,{pageSize,selectedId}),compareIds=new Set();
 let snapshot=null,lastResult=null,gridKey='',detailKey='',timer=null,composing=false,renderCount=0,mode='discover',previousMode='catalog',drawerOpen=false,detailTab='card',previewRank=null,equipPage=0,equipTarget=null,equipPlan=null,compareRank='current';
 const savedViews={catalog:null,collection:null};
 root.innerHTML=`<nav class="armory-mode-nav" aria-label="Armory workspace"><button id="shopDiscoverTab" aria-pressed="true">Discover</button><button id="shopCatalogTab" aria-pressed="false">Catalog</button><button id="shopCollectionTab" aria-pressed="false">My collection</button><button id="shopCompareOpen" aria-disabled="true">Compare <span id="shopCompareCount">0/2</span></button></nav><div class="armory-stage">
 <section id="shopDiscover" class="armory-discover" aria-label="Discover the armory"></section>
 <div id="shopBrowseView" class="armory-browser hidden"><aside class="armory-departments" aria-label="Browse departments"><div class="armory-rail-heading">Departments</div><div id="shopDepartmentRail"><button data-department="all" aria-pressed="true">All cards</button>${departments.map(dep=>`<button data-department="${escape(dep.id)}" aria-pressed="false">${escape(dep.name)}<span id="department-count-${escape(dep.id)}"></span></button>`).join('')}</div><p id="shopDepartmentHint" class="armory-department-hint"></p><div id="shopFilters" class="armory-subtypes" role="group" aria-label="Ability delivery">${ARMORY_CATEGORIES.map(([id,label])=>`<button data-ability-filter="${id}" aria-pressed="${id==='all'}">${label}</button>`).join('')}</div></aside>
 <section id="shopCatalogScroll" class="armory-catalog" tabindex="0" aria-label="Armory card catalog"><div class="armory-browser-heading"><div><span id="shopContext" class="eyebrow">THE CATALOG</span><h3 id="shopDepartmentTitle">All cards</h3></div><button id="shopClear" type="button">Reset view</button></div>
 <form id="shopSearchForm" class="armory-search-row" role="search"><label class="armory-search"><span class="catalog-sr-only">Search armory cards</span><input id="shopSearch" type="search" maxlength="200" placeholder="Find a card, effect or role…" autocomplete="off" aria-controls="shopGrid"></label><label class="armory-compact-category"><span class="catalog-sr-only">Department</span><select id="shopDepartmentCompact">${options([['all','All cards'],...departments.map(dep=>[dep.id,dep.name])])}</select></label><button id="shopFilterToggle" type="button" aria-expanded="${startRefined}" aria-controls="shopAdvancedFilters">Refine</button></form>
 <div id="shopAdvancedFilters" class="armory-refinements${startRefined?'':' hidden'}"><label>Ownership<select id="shopOwnership">${options(ARMORY_STATUSES)}</select></label><label id="shopTraitField">Effect / role<select id="shopTrait">${options(ARMORY_TRAITS)}</select></label><label id="shopRoleField">Army role<select id="shopRole">${options(roles)}</select></label><label id="shopDeliveryField">Delivery<select id="shopCategoryCompact">${options(ARMORY_CATEGORIES)}</select></label><label>Sort by<select id="shopSort">${options(ARMORY_SORTS)}</select></label></div>
 <div id="shopPinnedTray" class="armory-pinned-tray" aria-label="Pinned comparison cards"></div><div class="armory-results-line"><p id="shopResultCount" role="status" aria-live="polite" aria-atomic="true"></p><span id="shopFilterSummary"></span></div><div id="shopCardScroll" class="armory-scroll"><div class="shop-grid" id="shopGrid" role="list"></div><nav class="armory-pagination" aria-label="Catalog pages"><button id="shopPrevious">Previous</button><span id="shopPageLabel"></span><button id="shopNext">Next</button></nav></div></section></div>
 <aside id="shopDetailDrawer" class="armory-details hidden" aria-label="Selected card workspace"><div class="armory-detail-nav"><button id="shopCloseDetails">Back to cards</button><label class="armory-detail-mode-compact"><span class="catalog-sr-only">Card workspace</span><select id="shopDetailMode"><option value="card">Card</option><option value="stats">Stats &amp; ranks</option><option value="equip">Loadout</option></select></label><button id="shopPinSelected" aria-pressed="false">Pin to compare</button></div><div class="armory-detail-tabs" role="group" aria-label="Card workspace"><button data-detail-tab="card" aria-pressed="true">Card</button><button data-detail-tab="stats" aria-pressed="false">Stats & ranks</button><button data-detail-tab="equip" aria-pressed="false">Loadout</button></div><section id="shopDetails" aria-label="Selected card details"></section></aside>
 <section id="shopCompareView" class="armory-compare hidden" aria-label="Compare selected cards"></section></div>`;
 const $=selector=>root.querySelector(selector),focus=id=>{const target=$('#'+id);if(!target||target.disabled||target.getClientRects?.().length===0)return null;target.focus?.({preventScroll:true});return target;};
 const itemName=id=>model.byId.get(id)?.name??nameForId(id);
 const say=text=>announce(text);
 function restoreFocus(id){if(!id)return;if(!focus(id))focus('shopDetailAction')||focus('shopCloseDetails')||focus('inspect-'+model.selectedId)||focus('shopSearch')||focus('shopCompareOpen');}
 function showStage(){
  $('#shopDiscover').classList.toggle('hidden',mode!=='discover');$('#shopBrowseView').classList.toggle('hidden',mode==='discover'||mode==='compare');$('#shopCompareView').classList.toggle('hidden',mode!=='compare');
  $('#shopDetailDrawer').classList.toggle('hidden',!drawerOpen||mode==='discover'||mode==='compare');$('.armory-stage').classList.toggle('detail-open',drawerOpen&&['catalog','collection'].includes(mode));
  for(const [id,value]of [['shopDiscoverTab','discover'],['shopCatalogTab','catalog'],['shopCollectionTab','collection']])$('#'+id).setAttribute('aria-pressed',String(mode===value));
  $('#shopCompareOpen').setAttribute('aria-pressed',String(mode==='compare'));$('#shopCompareOpen').setAttribute('aria-disabled',String(compareIds.size<2));$('#shopCompareCount').textContent=`${compareIds.size}/2`;
 }
 function changeMode(next,{department,query,focusId}={}){
  if(mode==='catalog'||mode==='collection'){savedViews[mode]={...model.view};previousMode=mode;}
  const cameFrom=mode;mode=next;
  if(next==='catalog'||next==='collection'){
   if(cameFrom!==next){const saved=savedViews[next];if(saved)model.view={...saved};else model.setView({query:'',department:'all',role:'all',category:'all',trait:'all',status:'all',sort:'catalog'});model.setView({collection:next==='collection'});}
   if(department!==undefined)model.setView({department,category:'all',trait:'all',role:'all'});if(query!==undefined)model.setView({query});
  }
  drawerOpen=false;refresh();if(focusId)focus(focusId);
 }
 function syncControls(){
  const dep=departments.find(dep=>dep.id===model.view.department),collection=model.view.collection;
  for(const [id,key]of [['shopSearch','query'],['shopOwnership','status'],['shopTrait','trait'],['shopSort','sort'],['shopCategoryCompact','category'],['shopDepartmentCompact','department'],['shopRole','role']])if($('#'+id).value!==model.view[key])$('#'+id).value=model.view[key];
  for(const button of $('#shopDepartmentRail').querySelectorAll('button'))button.setAttribute('aria-pressed',String(button.getAttribute('data-department')===model.view.department));
  for(const button of $('#shopFilters').querySelectorAll('button'))button.setAttribute('aria-pressed',String(button.getAttribute('data-ability-filter')===model.view.category));
  $('#shopContext').textContent=collection?'YOUR COLLECTION':'THE CATALOG';$('#shopDepartmentTitle').textContent=dep?.name??(collection?'All owned cards':'All cards');$('#shopDepartmentHint').textContent=dep?.action??'Choose a department for relevant filters and card-specific details.';
  $('#shopRoleField').classList.toggle('hidden',model.view.department!=='army');$('#shopDeliveryField').classList.toggle('hidden',model.view.department!=='bow');$('#shopTraitField').classList.toggle('hidden',dep?.facets.length===0);
  $('#shopFilters').classList.toggle('hidden',model.view.department!=='bow');
  for(const option of $('#shopOwnership').querySelectorAll('option'))option.hidden=collection&&!['all','equipped','reserve'].includes(option.value);
  $('#shopSearch').placeholder=collection?'Search your collection…':'Find a card, effect or role…';
  const allowed=dep?new Set(['all',...dep.facets]):null;for(const option of $('#shopTrait').querySelectorAll('option'))option.hidden=!!allowed&&!allowed.has(option.value);
  const count=['department','role','category','trait','status'].filter(key=>model.view[key]!=='all').length+(model.view.query.trim()?1:0);$('#shopFilterToggle').textContent=count?`Refine (${count})`:'Refine';$('#shopFilterSummary').textContent=count?`${count} active ${count===1?'filter':'filters'}`:'';
 }
 function renderDiscover(){
  const count=(predicate)=>model.records.filter(item=>predicate(item,armoryCardState(item,snapshot))).length;
  const collection=count((item,state)=>state.owned),available=count((item,state)=>item.storefront!==false&&state.eligible),reserve=count((item,state)=>state.owned&&!state.equipped);
  $('#shopDiscover').innerHTML=`<div class="armory-discover-heading"><div><span class="eyebrow">YOUR NEXT BATTLE STARTS HERE</span><h3>Build your battle plan</h3><p>Browse by how a card plays. Compare your options, then place them in your loadout.</p></div><button id="shopResumeBrowse">${savedViews.catalog?'Continue browsing':'Browse all cards'}</button></div><div class="armory-department-cards">${departments.map(dep=>{const items=model.records.filter(item=>item.department===dep.id&&item.storefront!==false),owned=items.filter(item=>armoryCardState(item,snapshot).owned).length;return `<button class="armory-department-card" data-discover-department="${escape(dep.id)}"><span class="department-art" aria-hidden="true">${items.slice(0,3).map(item=>`<span class="skill-icon">${icon(item.id)}</span>`).join('')}</span><strong>${escape(dep.name)}</strong><span>${escape(dep.description)}</span><small>${items.length} cards · ${owned} owned</small><b>${escape(dep.action)}</b></button>`;}).join('')}</div><div class="armory-discovery-shelves"><section><h4>Ready for your gold</h4><p>${available} ${available===1?'card is':'cards are'} available to acquire with ${number(snapshot.gold)} gold.</p><button id="shopAffordableShelf">Explore available cards</button></section><section><h4>Your collection</h4><p>${collection} owned · ${reserve} in reserve. Review your bindings and squad automation.</p><button id="shopCollectionShelf">Manage owned cards</button></section><section><h4>Explore a battle role</h4><div class="armory-role-jumps"><button data-discover-role="airborne">Airborne army</button><button data-discover-role="healing">Healing & support</button><button data-discover-role="ice">Ice & slowing</button></div></section></div>`;
  $('#shopResumeBrowse').onclick=()=>changeMode('catalog',{focusId:'shopSearch'});$('#shopCollectionShelf').onclick=()=>{changeMode('collection');model.setView({query:'',department:'all',role:'all',category:'all',trait:'all',status:'all'});refresh({resetScroll:true});focus('shopSearch');};
  $('#shopAffordableShelf').onclick=()=>{changeMode('catalog');model.setView({query:'',department:'all',role:'all',category:'all',trait:'all',status:'available'});refresh({resetScroll:true});focus('shopSearch');};
  for(const button of $('#shopDiscover').querySelectorAll('[data-discover-department]'))button.onclick=()=>{changeMode('catalog',{department:button.getAttribute('data-discover-department'),query:''});model.setView({status:'all'});refresh({resetScroll:true});focus('shopSearch');};
  for(const button of $('#shopDiscover').querySelectorAll('[data-discover-role]'))button.onclick=()=>{changeMode('catalog',{department:'all',query:''});model.setView({status:'all',trait:button.getAttribute('data-discover-role')});refresh({resetScroll:true});focus('shopSearch');};
 }
 function refresh({resetScroll=false,focusId=null}={}){
  clearTimeout(timer);timer=null;snapshot=getSnapshot();lastResult=model.query(snapshot);syncControls();showStage();if(mode==='discover')renderDiscover();
  for(const dep of departments){const count=model.records.filter(item=>item.department===dep.id&&(model.view.collection?armoryCardState(item,snapshot).owned:item.storefront!==false)).length;$('#department-count-'+dep.id).textContent=String(count);}
  const result=lastResult,activeId=focusId??document.activeElement?.id,scroll=$('#shopCatalogScroll'),scrollTop=scroll.scrollTop??0;
  const nextGridKey=result.items.map(item=>[item.id,stateKey(armoryCardState(item,snapshot)),item.id===model.selectedId,compareIds.has(item.id)].join('/')).join('|');
  const activeInGrid=Array.from($('#shopGrid').querySelectorAll('button')).some(node=>node.id===activeId),activeInDetail=Array.from($('#shopDetails').querySelectorAll('button,input,select')).some(node=>node.id===activeId);let needsFocus=Array.from($('#shopPinnedTray').querySelectorAll('button')).some(node=>node.id===activeId);
  if(gridKey!==nextGridKey||!gridKey){gridKey=nextGridKey;renderCount++;$('#shopGrid').innerHTML=result.items.length?result.items.map(item=>{
   const state=armoryCardState(item,snapshot),selected=item.id===model.selectedId,pinned=compareIds.has(item.id);
   return `<article class="shop-card${state.owned?' owned':''}${item.kind==='companion'?' companion-catalog-card':''}" data-selected="${selected}" role="listitem"><div class="card-kicker"><span>${escape(categoryLabel(item.category))}</span><span>${item.kind==='companion'?'Separate slot':`${number(item.reloadSeconds)}s reload`}</span></div><button id="inspect-${item.id}" class="shop-inspect" aria-pressed="${selected}" aria-controls="shopDetailDrawer" aria-label="Inspect ${escape(item.name)}. ${escape(statusLabel(item,state))}"><span class="skill-icon" aria-hidden="true">${icon(item.id)}</span><span><strong>${escape(item.name)}</strong><small>${state.owned?(item.kind==='companion'?'Companion collection':escape(bindingLabel(state.skill?.binding??-1))):`${number(item.price)} gold`}</small></span></button><p class="shop-card-description">${escape(item.description)}</p><p class="card-state" data-state="${state.owned?'owned':state.eligible?'available':'unaffordable'}">${escape(statusLabel(item,state))}</p><div class="shop-card-actions"><button id="compare-${item.id}" class="shop-compare-card" aria-pressed="${pinned}" aria-label="${pinned?'Remove':'Pin'} ${escape(item.name)} ${pinned?'from':'to'} comparison">${pinned?'Pinned':'Compare'}</button><button id="buy-${item.id}" class="shop-buy" aria-label="${escape(item.name)}. ${escape(actionLabel(item,state))}" ${!state.owned&&!state.eligible?'disabled':''}>${escape(actionLabel(item,state))}</button></div></article>`;
  }).join(''):'<div class="armory-empty"><strong>No cards match this view.</strong><p>Try another department, clear a filter, or search for a different role.</p><button id="shopEmptyReset">Reset view</button></div>';
  for(const item of result.items){$('#inspect-'+item.id).onclick=()=>select(item.id);$('#buy-'+item.id).onclick=()=>act(item.id,'buy-'+item.id);$('#compare-'+item.id).onclick=()=>toggleCompare(item.id,'compare-'+item.id);}
  if($('#shopEmptyReset'))$('#shopEmptyReset').onclick=reset;needsFocus=needsFocus||activeInGrid;}
  scroll.scrollTop=resetScroll?0:scrollTop;$('#shopResultCount').textContent=result.total?`${number(result.start+1)}–${number(result.end)} of ${number(result.total)} cards`:'0 cards';$('#shopPageLabel').textContent=`Page ${result.page+1} of ${result.pageCount}`;$('#shopPrevious').setAttribute('aria-disabled',String(result.page===0));$('#shopNext').setAttribute('aria-disabled',String(result.page===result.pageCount-1));
  $('#shopPinnedTray').innerHTML=[...compareIds].map(id=>`<button id="unpin-${id}" aria-label="Remove ${escape(itemName(id))} from comparison">${escape(itemName(id))}<span aria-hidden="true">×</span></button>`).join('');for(const id of compareIds)$('#unpin-'+id).onclick=()=>toggleCompare(id,'shopCompareOpen');
  const item=model.byId.get(model.selectedId),state=item?armoryCardState(item,snapshot):null;
  const bindingKey=[...(snapshot.bindings??new Map())].map(([slot,skill])=>`${slot}:${skill.id}`).join(',');
  const nextDetailKey=item?[item.id,stateKey(state),result.selectedOnPage,result.selectedIndex<0,detailTab,previewRank,equipPage,equipTarget,snapshot.heroRank,snapshot.difficulty,bindingKey].join('/'):'';
  if(detailKey!==nextDetailKey||!detailKey){detailKey=nextDetailKey;renderDetail(item,state,result);needsFocus=needsFocus||activeInDetail;}
  $('#shopDetailMode').value=detailTab;$('#shopPinSelected').setAttribute('aria-pressed',String(compareIds.has(model.selectedId)));$('#shopPinSelected').textContent=compareIds.has(model.selectedId)?'Remove comparison':'Pin to compare';for(const button of $('.armory-detail-tabs').querySelectorAll('button'))button.setAttribute('aria-pressed',String(button.getAttribute('data-detail-tab')===detailTab));
  if(mode==='compare')renderComparison();if(focusId||needsFocus)restoreFocus(activeId);return result;
 }
 function detailHeader(item,state,result){return `<div class="armory-detail-location${result.selectedOnPage?' on-page':''}"><button id="shopBrowse" class="armory-browse">${result.selectedOnPage?'Show card in catalog':'Show in catalog'}</button>${!result.selectedOnPage?`<span>${result.selectedIndex<0?'Selected outside these filters':'Selected on another page'}</span>`:''}</div><div class="armory-detail-title"><span class="skill-icon" aria-hidden="true">${icon(item.id)}</span><div><span class="eyebrow">${escape(item.kind==='companion'?'COMPANION · SEPARATE SLOT':categoryLabel(item.category))}</span><h3>${escape(item.name)}</h3>${item.title?`<p class="card-subtitle">${escape(item.title)}</p>`:''}</div></div><p class="armory-eligibility">${escape(statusLabel(item,state))}${state.owned&&item.kind==='skill'?` · ${escape(bindingLabel(state.skill?.binding??-1))}`:''}</p><button id="shopDetailAction" aria-label="${escape(item.name)}. ${escape(actionLabel(item,state))}" ${!state.owned&&!state.eligible?'disabled':''} class="${state.eligible?'primary':''}">${escape(actionLabel(item,state))}</button>`;}
 function renderDetail(item,state,result){
  if(!item){$('#shopDetails').innerHTML='<p>Choose a card to inspect its role, progression and loadout.</p>';return;}
  const companion=item.kind==='companion';let body='';
  if(detailTab==='stats')body=statsMarkup(item,state);
  else if(detailTab==='equip')body=equipMarkup(item,state);
  else{
   const insight=getCardInsights(item,{rank:state.skill?.rank??0,heroRank:snapshot.heroRank,difficulty:snapshot.difficulty});
   const facts=companion?[['Hire cost',`${number(item.price)} gold`],['Summon cost',`${number(item.summonCost)} gold · no reserve`],[item.signatureName,`${item.signatureSeconds}s reload`],['Recall / defeat recovery',`${item.recallSeconds}s / ${item.defeatSeconds}s`]]:[['Unlock cost',item.storefront===false?'Starting ability':`${number(item.price)} gold`],['Reload',`${number(item.reloadSeconds)} seconds`],['Ability rank',state.owned?`${state.skill?.rank??0} / 10`:'Starts at rank 0'],...(item.squad?[['Per squad',`${item.squad.gold} gold · ${item.squad.reserve} reserve`],['Squad size',`${item.squad.size} ${item.squad.size===1?'unit':'units'}`]]:[]),...(item.alliedProtection?[['Friendly fire','Protected from allied attacks']]:[])];
   body=`<p class="card-description-full">${escape(item.description)}</p>${item.traits.length?`<p class="armory-traits">${item.traits.map(trait=>`<span>${escape(traitLabel(trait))}</span>`).join('')}</p>`:''}<dl class="armory-facts">${facts.map(([key,value])=>`<div><dt>${escape(key)}</dt><dd>${escape(value)}</dd></div>`).join('')}</dl>${insight.tactics.length?`<section class="armory-tactics"><h4>On the battlefield</h4><ul>${insight.tactics.map(text=>`<li>${escape(text)}</li>`).join('')}</ul></section>`:''}<p class="armory-price-note">${companion?'New recreation feature. Costs and recovery times are provisional balance choices. Hiring persists; you pay the summon cost each time you summon.':`${escape(insight.progression.description)} Keep at least 1 gold after purchasing. No hero rank requirement.`}</p>`;
  }
  $('#shopDetails').innerHTML=detailHeader(item,state,result)+body;
  $('#shopBrowse').onclick=()=>{const fresh=armoryCardState(item,getSnapshot());if(item.storefront===false&&!model.view.collection)changeMode('collection');else if(!fresh.owned&&model.view.collection)changeMode('catalog');model.revealSelected(getSnapshot());if(mode==='discover'||mode==='compare')mode=previousMode;drawerOpen=false;refresh({resetScroll:true});const target=focus('inspect-'+item.id);target?.scrollIntoView?.({block:'nearest',behavior:'auto'});};
  $('#shopDetailAction').onclick=()=>act(item.id,'shopDetailAction');
  if(detailTab==='stats')$('#shopPreviewRank').onchange=()=>{previewRank=Number($('#shopPreviewRank').value);detailKey='';refresh({focusId:'shopPreviewRank'});};
  if(detailTab==='equip')wireEquip(item,state);
 }
 function statsMarkup(item,state){
  const preview=getRankPreview(item,snapshot,previewRank??undefined),current=preview.current,next=preview.preview,rankLabel=current.progression.kind==='hero'?'Hero rank':'Ability rank';
  const fields=current.metrics.map(metric=>{const other=next.metrics.find(value=>value.key===metric.key),delta=other?other.value-metric.value:0;return `<tr><th scope="row">${escape(metric.label)}<small>${escape(metric.scope)}</small></th><td>${escape(metricValue(metric))}</td><td>${escape(metricValue(other))}${delta?`<small class="stat-delta">${delta>0?'+':''}${number(delta)}</small>`:''}</td></tr>`;}).join('');
  return `<section class="armory-rank-preview"><div class="armory-section-title"><h4>Stats & progression</h4><span>${escape(snapshot.difficulty??'medium')} difficulty</span></div><p>${escape(current.progression.description)}</p>${state.skill?`<p class="armory-xp">${number(state.skill.xp??0)} / ${number(state.skill.threshold??100)} XP · ${state.skill.rank>=10?'Maximum rank':'Next rank after passing this threshold'}</p>`:''}<label class="armory-preview-select">Preview ${rankLabel.toLowerCase()}<select id="shopPreviewRank">${Array.from({length:preview.maxRank-(current.progression.kind==='hero'?1:0)+1},(_,i)=>i+(current.progression.kind==='hero'?1:0)).map(rank=>`<option value="${rank}" ${rank===next.progression.rank?'selected':''}>${rankLabel} ${rank}</option>`).join('')}</select></label><p class="armory-preview-note">Preview only. This does not spend gold or change your card.</p><table class="armory-stat-table"><thead><tr><th>Measure</th><th>Current<br>${rankLabel} ${current.progression.rank}</th><th>Preview<br>${rankLabel} ${next.progression.rank}</th></tr></thead><tbody>${fields}</tbody></table><ul class="armory-stat-notes">${current.notes.map(text=>`<li>${escape(text)}</li>`).join('')}</ul></section>`;
 }
 function equipMarkup(item,state){
  if(!state.owned)return `<section class="armory-equip"><h4>Acquire before equipping</h4><p>${item.kind==='companion'?'Hire this companion to equip the separate companion slot.':'Unlock this ability, then choose its action bar and key here.'}</p></section>`;
  if(item.kind==='companion')return `<section class="armory-equip"><h4>Your companion slot</h4><p>${state.equipped?`${escape(item.name)} is equipped.`:'The companion is owned and in reserve.'} This slot is separate from all 30 ability bindings.</p><button id="shopCompanionEquip">${state.equipped?'Unequip companion':'Equip companion'}</button><p>Costs ${item.summonCost} gold each time you summon. It uses no reserve or regular army slot.</p></section>`;
  const skill=state.skill,bindings=snapshot.bindings??new Map(),target=equipTarget===null?null:bindings.get(equipTarget),from=skill?.binding??-1;
  const summary=equipTarget===null?'Choose a destination. Review the change before applying it.':equipTarget===-1?`${item.name} will move to reserve. It remains owned.`:target?.id===item.id?`${item.name} is already in ${bindingLabel(equipTarget)}.`:target?(from>=0?`${item.name} and ${itemName(target.id)} will swap places.`:`${item.name} will take ${bindingLabel(equipTarget)}. ${itemName(target.id)} will move to reserve.`):`${item.name} will move to ${bindingLabel(equipTarget)}.`;
  return `<section class="armory-equip"><div class="armory-section-title"><h4>Place in your loadout</h4><span>${escape(bindingLabel(from))}</span></div><div class="armory-equip-pages" role="group" aria-label="Choose action bar">${[0,1,2].map(page=>`<button data-equip-page="${page}" aria-pressed="${page===equipPage}">Bar ${page+1}</button>`).join('')}</div><div class="armory-quick-slots" role="group" aria-label="Choose a destination key">${Array.from({length:10},(_,slot)=>{const index=equipPage*10+slot,occupant=bindings.get(index);return `<button id="shop-slot-${index}" aria-pressed="${equipTarget===index}" aria-label="Bar ${equipPage+1}, key ${keyLabel(slot)}. ${escape(occupant?itemName(occupant.id):'Empty')}. Preview assignment."><b>${keyLabel(slot)}</b><span class="skill-icon" aria-hidden="true">${occupant?icon(occupant.id):''}</span><small>${escape(occupant?itemName(occupant.id):'Empty')}</small></button>`;}).join('')}</div><div class="armory-equip-review"><p id="shopEquipPreview" role="status">${escape(summary)}</p><div><button id="shopEquipConfirm" ${equipTarget===null||equipTarget===from?'disabled':''}>Apply placement</button><button id="shopEquipCancel" ${equipTarget===null?'disabled':''}>Cancel</button><button id="shopReserve" ${from<0?'disabled':''}>Move to reserve</button></div></div><button id="shopOpenFullLoadout">Open full loadout editor</button>${item.squad?`<label class="armory-autocast"><input id="shopAutoSummon" type="checkbox" ${skill?.autocast?'checked':''}><span>Auto-summon this squad<small>While equipped, queues when ready if gold, reserve and army capacity allow.</small></span></label>`:''}</section>`;
 }
 function wireEquip(item,state){
  if(!state.owned)return;
  if(item.kind==='companion'){$('#shopCompanionEquip').onclick=()=>{onCompanionEquip(item,!state.equipped);detailKey='';refresh({focusId:'shopCompanionEquip'});};return;}
  for(const button of $('#shopDetails').querySelectorAll('[data-equip-page]'))button.onclick=()=>{equipPage=Number(button.getAttribute('data-equip-page'));equipTarget=null;detailKey='';refresh();$('#shopDetails').querySelector(`[data-equip-page="${equipPage}"]`)?.focus?.({preventScroll:true});};
  for(let slot=equipPage*10;slot<equipPage*10+10;slot++)$('#shop-slot-'+slot).onclick=()=>{equipTarget=slot;const fresh=getSnapshot();equipPlan={id:item.id,from:fresh.skills.get(item.id)?.binding??-1,to:slot,occupant:fresh.bindings?.get(slot)?.id??null};detailKey='';refresh({focusId:'shop-slot-'+slot});};
  $('#shopEquipCancel').onclick=()=>{equipTarget=null;detailKey='';refresh({focusId:'shop-slot-'+equipPage*10});};
  $('#shopReserve').onclick=()=>{equipTarget=-1;equipPlan={id:item.id,from:getSnapshot().skills.get(item.id)?.binding??-1,to:-1,occupant:null};detailKey='';refresh({focusId:'shopEquipConfirm'});};
  $('#shopEquipConfirm').onclick=()=>{const fresh=getSnapshot(),current=armoryCardState(item,fresh);if(!current.owned||equipTarget===null)return;if(!equipPlan||equipPlan.id!==item.id||equipPlan.from!==(current.skill?.binding??-1)||equipPlan.occupant!==(fresh.bindings?.get(equipTarget)?.id??null)){equipTarget=null;equipPlan=null;detailKey='';refresh({focusId:'shop-slot-'+equipPage*10});say('Your loadout changed. Choose a destination again before applying.');return;}const result=onEquip(item,equipTarget);if(result!==false){equipTarget=null;detailKey='';refresh({focusId:'shop-slot-'+equipPage*10});}};
  $('#shopOpenFullLoadout').onclick=()=>onArrange(item);
  if($('#shopAutoSummon'))$('#shopAutoSummon').onchange=()=>{onAutocast(item,$('#shopAutoSummon').checked);detailKey='';refresh({focusId:'shopAutoSummon'});};
 }
 function renderComparison(){
  const items=[...compareIds].map(id=>model.byId.get(id)).filter(Boolean);if(items.length<2){mode=previousMode;showStage();return;}
  const insights=items.map(item=>{const state=armoryCardState(item,snapshot);return getCardInsights(item,{rank:compareRank==='current'?state.skill?.rank??0:Number(compareRank),heroRank:snapshot.heroRank,difficulty:snapshot.difficulty});});
  const common=[{key:'acquire',label:'Acquisition cost',values:items.map(item=>`${number(item.price)} gold`)},{key:'ownership',label:'Collection',values:items.map(item=>statusLabel(item,armoryCardState(item,snapshot)))}];
  const keys=[...new Set(insights.flatMap(insight=>insight.metrics.map(metric=>metric.key)))];
  const rows=[...common,...keys.map(key=>{const metric=insights.flatMap(insight=>insight.metrics).find(metric=>metric.key===key);return {key,label:metric.label,scope:metric.scope,values:insights.map(insight=>metricValue(insight.metrics.find(metric=>metric.key===key)))};})];
  $('#shopCompareView').innerHTML=`<div class="armory-comparison-heading"><div><span class="eyebrow">MAKE YOUR NEXT CHOICE</span><h3>Compare cards</h3></div><button id="shopCompareBack">Back to ${previousMode==='collection'?'collection':'catalog'}</button></div><label class="armory-compare-rank">Compare ability ranks<select id="shopCompareRank">${options([['current','Current owned ranks'],...Array.from({length:11},(_,rank)=>[String(rank),`Both at rank ${rank}`])])}</select></label><p class="armory-preview-note">Companions use your hero rank. Different attack types are shown separately; these are not total damage-per-second figures.</p><table class="armory-comparison-table"><thead><tr><th scope="col">Measure</th>${items.map((item,i)=>`<th scope="col"><span class="skill-icon" aria-hidden="true">${icon(item.id)}</span><strong>${escape(item.name)}</strong><small>${insights[i].progression.kind==='hero'?'Hero':'Ability'} rank ${insights[i].progression.rank}</small><button id="comparison-inspect-${item.id}">Inspect card</button></th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr><th scope="row">${escape(row.label)}${row.scope?`<small>${escape(row.scope)}</small>`:''}</th>${row.values.map(value=>`<td>${escape(value)}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">Battlefield use</th>${insights.map(insight=>`<td><ul>${insight.tactics.map(text=>`<li>${escape(text)}</li>`).join('')}</ul></td>`).join('')}</tr></tbody></table><div class="armory-comparison-notes">${items.map((item,i)=>`<section><h4>${escape(item.name)}</h4><ul>${insights[i].notes.map(text=>`<li>${escape(text)}</li>`).join('')}</ul><button id="comparison-remove-${item.id}">Remove from comparison</button></section>`).join('')}</div>`;
  $('#shopCompareRank').value=compareRank;$('#shopCompareRank').onchange=()=>{compareRank=$('#shopCompareRank').value;renderComparison();focus('shopCompareRank');};$('#shopCompareBack').onclick=()=>{mode=previousMode;refresh();focus('shopCompareOpen');};
  for(const item of items){$('#comparison-inspect-'+item.id).onclick=()=>{mode=previousMode;select(item.id);};$('#comparison-remove-'+item.id).onclick=()=>{mode=previousMode;toggleCompare(item.id,'shopCompareOpen');};}
 }
 function toggleCompare(id,focusId){if(compareIds.has(id))compareIds.delete(id);else if(compareIds.size<2)compareIds.add(id);else{say('Two cards are already pinned. Remove one before adding another.');return;}refresh({focusId});say(`${compareIds.size} of 2 cards pinned for comparison.`);}
 function select(id){const changed=model.selectedId!==id;model.select(id);if(changed){detailTab='card';previewRank=null;equipTarget=null;const state=armoryCardState(model.byId.get(id),getSnapshot());equipPage=Math.max(0,Math.floor((state.skill?.binding??0)/10));}if(mode==='discover'||mode==='compare')mode=previousMode;drawerOpen=true;refresh();focus('shopCloseDetails');$('#shopDetailDrawer').scrollTop=0;}
 function act(id,focusId){
  const item=model.byId.get(id);if(!item)return;const state=armoryCardState(item,getSnapshot());model.select(id);
  if(state.owned){if(mode==='discover'||mode==='compare')mode=previousMode;drawerOpen=true;detailTab='equip';equipTarget=null;const current=state.skill?.binding??0;equipPage=Math.max(0,Math.floor(current/10));detailKey='';refresh({focusId:'shopDetailAction'});$('#shopDetailDrawer').scrollTop=0;return;}
  if(!state.eligible){refresh({focusId});say(state.purchaseBlockedReason??`Need ${number(state.shortfall)} more gold for ${item.name}.`);return;}
  if(onPurchase(item)===false){refresh({focusId});return;}
  if(mode==='discover'||mode==='compare')mode=previousMode;drawerOpen=true;detailTab='equip';equipTarget=null;previewRank=null;const owned=armoryCardState(item,getSnapshot());equipPage=Math.max(0,Math.floor((owned.skill?.binding??0)/10));refresh({focusId:'shopDetailAction'});focus('shopDetailAction')?.scrollIntoView?.({block:'nearest',behavior:'auto'});
 }
 function reset(){model.setView({query:'',role:'all',category:'all',trait:'all',status:'all',sort:'catalog'});refresh({resetScroll:true});focus('shopSearch');}
 function change(patch){model.setView(patch);refresh({resetScroll:true});if('page'in patch&&lastResult.items[0]){const target=focus('inspect-'+lastResult.items[0].id);target?.scrollIntoView?.({block:'start',behavior:'auto'});}}
 function chooseDepartment(id){if(mode==='discover')mode='catalog';drawerOpen=false;change({department:id,category:'all',trait:'all',role:'all'});focus('shopSearch');}
 $('#shopDiscoverTab').onclick=()=>changeMode('discover');$('#shopCatalogTab').onclick=()=>changeMode('catalog');$('#shopCollectionTab').onclick=()=>changeMode('collection');$('#shopCompareOpen').onclick=()=>{if(compareIds.size<2){say('Pin two cards to compare their stats and roles.');return;}if(mode==='catalog'||mode==='collection'){previousMode=mode;savedViews[mode]={...model.view};}mode='compare';drawerOpen=false;refresh();focus('shopCompareBack');};
 $('#shopCloseDetails').onclick=()=>{drawerOpen=false;refresh();const target=focus('inspect-'+model.selectedId)||focus('shopSearch');target?.scrollIntoView?.({block:'nearest',behavior:'auto'});};$('#shopPinSelected').onclick=()=>toggleCompare(model.selectedId,'shopPinSelected');
 $('#shopDetailMode').onchange=()=>{detailTab=$('#shopDetailMode').value;equipTarget=null;detailKey='';refresh({focusId:'shopDetailMode'});$('#shopDetailDrawer').scrollTop=0;};
 for(const button of $('.armory-detail-tabs').querySelectorAll('button'))button.onclick=()=>{detailTab=button.getAttribute('data-detail-tab');equipTarget=null;detailKey='';refresh();button.focus?.({preventScroll:true});$('#shopDetailDrawer').scrollTop=0;};
 $('#shopSearchForm').onsubmit=event=>{event.preventDefault();refresh({resetScroll:true});};$('#shopSearch').oninput=()=>{model.setView({query:$('#shopSearch').value});clearTimeout(timer);if(!composing)timer=setTimeout(()=>refresh({resetScroll:true}),120);};$('#shopSearch').oncompositionstart=()=>{composing=true;clearTimeout(timer);};$('#shopSearch').oncompositionend=()=>{composing=false;change({query:$('#shopSearch').value});};
 for(const [id,key]of [['shopOwnership','status'],['shopTrait','trait'],['shopSort','sort'],['shopCategoryCompact','category'],['shopRole','role']])$('#'+id).onchange=()=>change({[key]:$('#'+id).value});$('#shopDepartmentCompact').onchange=()=>chooseDepartment($('#shopDepartmentCompact').value);
 for(const button of $('#shopDepartmentRail').querySelectorAll('button'))button.onclick=()=>chooseDepartment(button.getAttribute('data-department'));
 for(const button of $('#shopFilters').querySelectorAll('button'))button.onclick=()=>{if(mode==='discover')mode='catalog';const category=button.getAttribute('data-ability-filter');change({department:category==='army'?'army':category==='companions'?'companions':category==='all'?'all':'bow',category});};
 $('#shopFilterToggle').onclick=()=>{const expanded=$('#shopFilterToggle').getAttribute('aria-expanded')!=='true';$('#shopFilterToggle').setAttribute('aria-expanded',String(expanded));$('#shopAdvancedFilters').classList.toggle('hidden',!expanded);};$('#shopClear').onclick=reset;$('#shopPrevious').onclick=()=>{if(lastResult?.page>0)change({page:lastResult.page-1});};$('#shopNext').onclick=()=>{if(lastResult&&lastResult.page<lastResult.pageCount-1)change({page:lastResult.page+1});};
 return {refresh,select,back(){if(mode==='compare'){mode=previousMode;refresh();focus('shopCompareOpen');return true;}if(drawerOpen){$('#shopCloseDetails').onclick();return true;}return false;},get model(){return model;},get state(){return {mode,drawerOpen,detailTab,compareIds:[...compareIds]};},get diagnostics(){return {cardCount:lastResult?.items.length??0,renderCount,resultCount:lastResult?.total??0};},dispose(){clearTimeout(timer);}};
}
